def transform(grid):
    """Stamp the embedded colored line onto each isolated marker."""
    from collections import Counter, deque
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r][c] == bg or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.pop()
                comp.append((y, x, g[y][x]))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and g[yy][xx] != bg and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append(comp)
    motif_comp = max(comps, key=len)
    coords = [(r,c,v) for r,c,v in motif_comp]
    rows = {r for r,c,v in coords}; cols = {c for r,c,v in coords}
    if len(rows) == 1:
        coords.sort(key=lambda x:x[1])
        anchor = (coords[len(coords)//2][0], coords[len(coords)//2][1])
    elif len(cols) == 1:
        coords.sort(key=lambda x:x[0])
        anchor = (coords[len(coords)//2][0], coords[len(coords)//2][1])
    else:
        return g
    motif = [(r-anchor[0], c-anchor[1], v) for r,c,v in coords]
    motif_cells = {(r,c) for r,c,v in coords}
    marker_counts = Counter(v for comp in comps for r,c,v in comp if (r,c) not in motif_cells)
    if not marker_counts:
        return g
    marker = marker_counts.most_common(1)[0][0]
    points = [(r,c) for r in range(h) for c in range(w) if g[r][c] == marker and (r,c) not in motif_cells]
    for r,c in points:
        for dr,dc,v in motif:
            y,x = r+dr,c+dc
            if 0 <= y < h and 0 <= x < w:
                g[y][x] = v
    return g

